package com.pratik.imagetap;
import android.accessibilityservice.*;import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowAlertDialog;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w412dp-h892dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class Automation69Test {
 Context c;Recording service;MainActivity activity;
 public static class Recording extends TapService {int calls,global=-1;boolean accepted=true;GestureDescription gesture;GestureResultCallback callback;@Override protected boolean sendTapGesture(GestureDescription g,GestureResultCallback cb){calls++;gesture=g;callback=cb;return accepted;}@Override protected boolean sendNavigationAction(int a){global=a;return accepted;}}
 @Before public void setup(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("config",0).edit().putBoolean("reduceMotion",true).putBoolean("tap",true).commit();}
 @After public void cleanup(){if(activity!=null){activity.finish();}if(service!=null){service.stopSession("test");service.onDestroy();TapService.instance=null;}}
 TimedAction step(ActionType a,long wait){TimedAction t=TimedAction.create(a);return new TimedAction(t.id,"",a,t.x,t.y,t.endX,t.endY,wait,t.duration,true);}
 @Test public void waterfallWaitsAfterCompletion(){AutomationClock clock=new AutomationClock(Arrays.asList(step(ActionType.TAP,3400),step(ActionType.DOWN,1200)),true,false,0);assertEquals(-1,clock.take(3399));assertEquals(0,clock.take(3400));assertEquals(-1,clock.take(4600));clock.complete(3500);assertEquals(-1,clock.take(4699));assertEquals(1,clock.take(4700));clock.complete(5050);assertTrue(clock.done);assertEquals(-1,clock.take(9000));}
 @Test public void pauseFreezesRemainingTime(){AutomationClock clock=new AutomationClock(Arrays.asList(step(ActionType.TAP,3400)),true,false,0);clock.pause(2000);assertEquals(-1,clock.take(9000));clock.resume(12000);assertEquals(1400,clock.remaining(12000));assertEquals(0,clock.take(13400));}
 @Test public void completionWhilePausedStartsNextDelayOnResume(){AutomationClock clock=new AutomationClock(Arrays.asList(step(ActionType.TAP,100),step(ActionType.DOWN,1200)),true,false,0);clock.take(100);clock.pause(150);clock.complete(200);clock.resume(1000);assertEquals(1200,clock.remaining(1000));}
 @Test public void generalTimersNeverOverlapOrCatchUpInBursts(){AutomationClock clock=new AutomationClock(Arrays.asList(step(ActionType.TAP,1000),step(ActionType.DOWN,1500)),false,false,0);assertEquals(0,clock.take(1000));assertEquals(-1,clock.take(2000));clock.complete(2100);assertEquals(1,clock.take(2100));clock.complete(2450);assertEquals(-1,clock.take(2450));assertEquals(650,clock.remaining(2450));}
 @Test public void repeatTimelineRestartsWithFirstDelay(){AutomationClock clock=new AutomationClock(Arrays.asList(step(ActionType.TAP,200)),true,true,0);clock.take(200);clock.complete(300);assertFalse(clock.done);assertEquals(-1,clock.take(499));assertEquals(0,clock.take(500));}
 @Test public void failedStepRetriesWithoutAdvancing(){AutomationClock clock=new AutomationClock(Arrays.asList(step(ActionType.TAP,100),step(ActionType.BACK,100)),true,false,0);clock.take(100);clock.failed(200);assertEquals(0,clock.index);assertEquals(-1,clock.take(699));assertEquals(0,clock.take(700));}
 @Test public void savedModesRemainSeparateAndDisabledStepsAreFiltered(){TimedAction a=step(ActionType.LEFT,1000);AutomationStore.save(c,false,Arrays.asList(a));AutomationStore.save(c,true,Arrays.asList(step(ActionType.BACK,3400),step(ActionType.HOME,1200).enabled(false)));assertEquals(ActionType.LEFT,AutomationStore.load(c,false).get(0).action);assertEquals(2,AutomationStore.load(c,true).size());assertEquals(1,AutomationStore.active(c,true).size());assertEquals(3400,AutomationStore.active(c,true).get(0).delay);}
 @Test public void corruptOrInvalidDataDoesNotSilentlyDisappear(){c.getSharedPreferences("automation",0).edit().putString("timeline","bad data").commit();try{AutomationStore.load(c,true);fail();}catch(IllegalStateException expected){}assertEquals("bad data",c.getSharedPreferences("automation",0).getString("timeline",""));for(String value:new String[]{"NaN","Infinity","0","-1","3601"})try{AutomationUi.millis(value);fail(value);}catch(IllegalArgumentException expected){}assertEquals(3400,AutomationUi.millis("3.4"));}
 @Test public void illegalSwipeDirectionIsRejected(){try{new TimedAction(null,"",ActionType.LEFT,.2f,.5f,.8f,.5f,1000,350,true);fail();}catch(IllegalArgumentException expected){}}
 void createService(List<TimedAction> steps)throws Exception{service=Robolectric.buildService(Recording.class).create().get();Release67Test.set(service,"prefs",service.getSharedPreferences("config",0));Release67Test.set(service,"wm",service.getSystemService(Context.WINDOW_SERVICE));Method panel=TapService.class.getDeclaredMethod("showPanel");panel.setAccessible(true);panel.invoke(service);Release67Test.set(service,"running",true);Release67Test.set(service,"runMode","timeline");Release67Test.set(service,"automation",new AutomationClock(steps,true,false,SystemClock.elapsedRealtime()-1000));}
 void tick()throws Exception{Method m=TapService.class.getDeclaredMethod("nextAutomation",int.class);m.setAccessible(true);m.invoke(service,(Integer)Release67Test.get(service,"generation"));}
 @Test public void timedTapRunsWithoutAnyImagesAndCompletesOnCallback()throws Exception{createService(Arrays.asList(step(ActionType.TAP,100)));tick();assertEquals(1,service.calls);assertFalse(((AutomationClock)Release67Test.get(service,"automation")).done);service.callback.onCompleted(service.gesture);assertTrue(((AutomationClock)Release67Test.get(service,"automation")).done);assertEquals(1L,Release67Test.get(service,"taps"));}
 @Test public void timedHomeUsesAndroidNavigation()throws Exception{createService(Arrays.asList(step(ActionType.HOME,100)));tick();assertEquals(AccessibilityService.GLOBAL_ACTION_HOME,service.global);assertEquals(0,service.calls);assertTrue(((AutomationClock)Release67Test.get(service,"automation")).done);}
 @Test public void timedPreviewEditorAndPauseNeverDispatch()throws Exception{createService(Arrays.asList(step(ActionType.TAP,100)));service.editorOpen=true;tick();assertEquals(0,service.calls);service.editorOpen=false;service.getSharedPreferences("config",0).edit().putBoolean("tap",false).commit();tick();assertEquals(0,service.calls);service.getSharedPreferences("config",0).edit().putBoolean("tap",true).commit();((SessionPause)Release67Test.get(service,"pause")).manual=true;tick();assertEquals(0,service.calls);}
 @Test public void stopIgnoresLateTimedCompletion()throws Exception{createService(Arrays.asList(step(ActionType.TAP,100)));tick();service.stopSession("user");service.callback.onCompleted(service.gesture);assertEquals(0L,Release67Test.get(service,"taps"));assertNull(Release67Test.get(service,"automation"));}
 @Test public void pauseDuringGestureAllowsCompletionButBlocksNextStep()throws Exception{createService(Arrays.asList(step(ActionType.TAP,100),step(ActionType.BACK,100)));tick();service.togglePause();service.callback.onCompleted(service.gesture);assertEquals(1L,Release67Test.get(service,"taps"));assertEquals(-1,service.global);assertEquals(1,((AutomationClock)Release67Test.get(service,"automation")).index);}
 @Test public void rejectedTimedGestureDoesNotAdvance()throws Exception{createService(Arrays.asList(step(ActionType.TAP,100),step(ActionType.BACK,100)));service.accepted=false;tick();assertEquals(0,((AutomationClock)Release67Test.get(service,"automation")).index);assertEquals(-1,((AutomationClock)Release67Test.get(service,"automation")).pending);assertEquals(0L,Release67Test.get(service,"taps"));}
 @Test public void timelineScreenShowsSequenceAndControls()throws Exception{AutomationStore.save(c,true,Arrays.asList(step(ActionType.TAP,3400),step(ActionType.DOWN,1200)));activity=Robolectric.buildActivity(MainActivity.class).setup().get();Release67Test.tab(activity,4);View root=Release67Test.root(activity);assertNotNull(AutoBashUiTest.find(root,"Repeat timeline"));assertNotNull(AutoBashUiTest.find(root,"1  ↓  Wait 3.4 s"));assertNotNull(AutoBashUiTest.find(root,"2  ↓  Wait 1.2 s"));assertNotNull(AutoBashUiTest.find(root,"Start Timeline mode"));AutoBashUiTest.save(root,"timeline69",824,1656);}
 @Test public void generalEditorOffersMarkersAndInterval()throws Exception{activity=Robolectric.buildActivity(MainActivity.class).setup().get();AutomationUi.edit(activity,false,step(ActionType.LEFT,1000),true,()->{});AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();assertNotNull(AutoBashUiTest.find(dialog.getWindow().getDecorView(),"Interval after completion (seconds)"));assertNotNull(AutoBashUiTest.find(dialog.getWindow().getDecorView(),"Place marker on screen"));dialog.getButton(-1).performClick();assertEquals(1,AutomationStore.load(activity,false).size());}
 @Test public void quickSaveAsksDestinationBeforeCrop()throws Exception{Bitmap b=Bitmap.createBitmap(400,800,Bitmap.Config.ARGB_8888);try(FileOutputStream out=new FileOutputStream(new File(c.getCacheDir(),"quick-save.png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();activity=Robolectric.buildActivity(MainActivity.class,new Intent(c,MainActivity.class).putExtra("quickSave",true)).setup().get();AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();assertNotNull(dialog);assertEquals(7,dialog.getListView().getAdapter().getCount());dialog.getListView().performItemClick(dialog.getListView().getChildAt(5),5,5);assertEquals(ActionType.BACK,ActionType.selected(activity));assertNotNull(AutoBashUiTest.find(Release67Test.root(activity),"Save target"));}
 @Test public void markerPickerSupportsDragSaveAndCancel()throws Exception{float[][] selected={null};MarkerPicker picker=new MarkerPicker(c,step(ActionType.TAP,1000),p->selected[0]=p);picker.layout(0,0,824,1656);Bitmap b=Bitmap.createBitmap(824,1656,Bitmap.Config.ARGB_8888);picker.draw(new Canvas(b));for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(0,0,action,600,1000,0);picker.onTouchEvent(e);e.recycle();}assertEquals(600/824f,picker.x,.001);for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(0,0,action,picker.heading.centerX(),picker.heading.centerY(),0);picker.onTouchEvent(e);e.recycle();}assertTrue(picker.controlsBottom);picker.draw(new Canvas(b));AutoBashUiTest.save(picker,"marker-picker69",824,1656);for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(0,0,action,picker.save.centerX(),picker.save.centerY(),0);picker.onTouchEvent(e);e.recycle();}assertNotNull(selected[0]);assertEquals(picker.x,selected[0][0],0);b.recycle();}
}
